<script setup lang="ts">
import ListPager from '../../components/ListPager.vue'
import {useListPage} from '../../composables/useListPage'
import {apiCollection} from '../../api/collections'
import { computed, onMounted, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { api, ApiError, readableApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'

type Message={id:number;sender_name:string|null;body:string;is_system:boolean;created_at:string}
type Conversation={id:number;subject:string;item_id:string|null;item_title:string|null;claim_id:string|null;participants:{id:number;display_name:string}[];messages:Message[];updated_at:string}
const route=useRoute();const router=useRouter();const conversations=ref<Conversation[]>([]);const current=ref<Conversation|null>(null);const body=ref('');const loading=ref(true);const sending=ref(false);const error=ref('')
const selectedId=computed(()=>Number(route.params.conversationId||0))
async function loadList(){const response=await apiCollection<{data:{items:Conversation[]}}>('/messages/?page_size=100');conversations.value=response.data.items}
let detailVersion=0
const detailLoading=ref(false)
async function loadDetail(){const id=selectedId.value,ticket=++detailVersion;current.value=null;body.value='';error.value='';if(!id)return;detailLoading.value=true;try{const response=await api<{data:Conversation}>(`/messages/${id}/`);if(ticket===detailVersion&&id===selectedId.value)current.value=response.data}catch(reason){if(ticket===detailVersion)error.value=readableApiError(reason,'会话暂时无法打开，请重试。')}finally{if(ticket===detailVersion)detailLoading.value=false}}
async function load(){loading.value=true;error.value='';try{await loadList();await loadDetail()}catch(reason){error.value=readableApiError(reason,'无法读取站内消息')}finally{loading.value=false}}
async function send(){if(!current.value||current.value.id!==selectedId.value||detailLoading.value||sending.value||!body.value.trim())return;sending.value=true;error.value='';try{await api(`/messages/${current.value.id}/messages/`,{method:'POST',body:JSON.stringify({body:body.value})});body.value='';await loadDetail();await loadList()}catch(reason){error.value=readableApiError(reason,'发送失败')}finally{sending.value=false}}
function open(entry:Conversation){router.push(`/messages/${entry.id}`)}
onMounted(load);watch(()=>route.params.conversationId,loadDetail)
const {page:pagedConversationsPage,rows:pagedConversations}=useListPage(conversations)
</script>
<template><div class="page messages-page"><header><h1 class="page-title">站内消息</h1><p class="page-lead">仅在物品或认领授权范围内沟通；请勿发送密码、完整身份证号或支付信息。</p></header><p v-if="loading" class="state">正在建立私密会话视图…</p><p v-else-if="error&&!conversations.length" class="state error">{{error}}</p><section v-else class="message-layout"><aside class="panel inbox"><div class="inbox-head"><h2>会话</h2><span>{{conversations.length}}</span></div><button v-for="entry in pagedConversations" :key="entry.id" :class="{active:selectedId===entry.id}" @click="open(entry)"><span class="avatar"><AppIcon name="user"/></span><span><strong>{{entry.subject}}</strong><small>{{entry.item_title||'系统会话'}} · {{new Date(entry.updated_at).toLocaleString('zh-CN')}}</small></span><AppIcon name="arrow"/></button><div v-if="!conversations.length" class="mini-empty">尚无站内会话。</div><ListPager :page="pagedConversationsPage" :total="conversations.length" @change="pagedConversationsPage=$event"/></aside><main class="panel thread"><template v-if="current"><header><div><h2>{{current.subject}}</h2><p>{{current.participants.map(entry=>entry.display_name).join(' · ')}}</p></div><RouterLink v-if="current.claim_id" :to="`/claims/${current.claim_id}`">查看认领</RouterLink></header><div class="message-list"><article v-for="message in current.messages" :key="message.id" :class="{system:message.is_system}"><div><strong>{{message.is_system?'系统':message.sender_name}}</strong><time>{{new Date(message.created_at).toLocaleString('zh-CN')}}</time></div><p>{{message.body}}</p></article><div v-if="!current.messages.length" class="mini-empty">会话中尚无消息。</div></div><form @submit.prevent="send"><textarea aria-label="会话消息" v-model="body" maxlength="4000" placeholder="发送与认领核验相关的信息…"></textarea><div><small>{{body.length}} / 4000</small><button class="button button-brand" :disabled="sending||!body.trim()">发送</button></div></form></template><div v-else class="thread-empty"><p v-if="detailLoading" role="status">正在读取会话…</p><p v-else-if="error" role="alert">{{error}}</p><AppIcon name="user"/><h2>选择一个会话</h2><p>会话内容只对参与者与授权管理员可见。</p></div></main></section><p v-if="error&&conversations.length" class="notice error">{{error}}</p></div></template>
<style scoped>.message-layout{display:grid;grid-template-columns:360px 1fr;gap:16px;margin-top:34px;min-height:620px}.inbox,.thread{overflow:hidden;box-shadow:none}.inbox{align-self:start}.inbox-head{display:flex;justify-content:space-between;align-items:center;padding:20px}.inbox-head h2{margin:0}.inbox button{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;width:100%;padding:16px;color:var(--ct-text);border:0;border-top:1px solid var(--ct-border);background:transparent;text-align:left}.inbox button.active,.inbox button:hover{background:var(--ct-surface-raised)}.avatar{display:grid;place-items:center;width:38px;aspect-ratio:1;color:var(--ct-brand);border-radius:50%;background:rgba(141,48,46,.08)}.inbox strong,.inbox small{display:block}.inbox small{margin-top:5px;color:var(--ct-text-muted);font-size:10px}.thread{display:grid;grid-template-rows:auto 1fr auto;min-height:620px}.thread>header{display:flex;justify-content:space-between;align-items:center;padding:20px;border-bottom:1px solid var(--ct-border)}.thread h2,.thread p{margin:0}.thread header p{margin-top:5px;color:var(--ct-text-muted);font-size:11px}.thread header a{color:var(--ct-brand)}.message-list{display:grid;align-content:start;gap:12px;overflow:auto;max-height:460px;padding:22px}.message-list article{max-width:80%;padding:14px;border:1px solid var(--ct-border);border-radius:14px;background:var(--ct-bg-soft)}.message-list article.system{max-width:100%;color:var(--ct-text-muted);border-style:dashed}.message-list article>div{display:flex;justify-content:space-between;gap:20px}.message-list time{color:var(--ct-text-muted);font-size:10px}.message-list article p{margin-top:8px;line-height:1.65}.thread form{padding:18px;border-top:1px solid var(--ct-border)}.thread textarea{width:100%;min-height:90px;padding:13px;color:var(--ct-text);border:1px solid var(--ct-border);border-radius:11px;background:var(--ct-bg-soft)}.thread form>div{display:flex;justify-content:space-between;align-items:center;margin-top:8px;color:var(--ct-text-muted)}.thread-empty,.state{display:grid;place-items:center;align-content:center;min-height:320px;color:var(--ct-text-muted);text-align:center}.thread-empty>svg{font-size:42px;color:var(--ct-brand)}.mini-empty{padding:30px;color:var(--ct-text-muted);text-align:center}.error{color:var(--ct-danger)}@media(max-width:850px){.message-layout{grid-template-columns:1fr}.inbox{max-height:330px;overflow:auto}}</style>
